package com.whaa.shop.user.controller;import com.whaa.shop.common.api.ApiResponse;import com.whaa.shop.common.security.CurrentUser;import com.whaa.shop.user.application.AddressService;import com.whaa.shop.user.domain.UserAddress;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/shop/addresses") public class AddressController {private final AddressService service;public AddressController(AddressService s){service=s;}@GetMapping ApiResponse<List<UserAddress>> list(){return ApiResponse.ok(service.list(CurrentUser.id()));}@PostMapping ApiResponse<UserAddress> create(@RequestBody UserAddress a){a.setId(null);return ApiResponse.ok(service.save(CurrentUser.id(),a));}@PutMapping("/{id}")ApiResponse<UserAddress> update(@PathVariable Long id,@RequestBody UserAddress a){a.setId(id);return ApiResponse.ok(service.save(CurrentUser.id(),a));}@PatchMapping("/{id}/default")ApiResponse<Void> setDefault(@PathVariable Long id){service.defaultAddress(CurrentUser.id(),id);return ApiResponse.ok();}@DeleteMapping("/{id}")ApiResponse<Void> delete(@PathVariable Long id){service.delete(CurrentUser.id(),id);return ApiResponse.ok();}}
